  "settings.magicPrompts.page.group.sessionSummary.title": "ملخص الجلسة",
  "settings.magicPrompts.page.group.sessionSummary.description": "المطالبات المستخدمة بواسطة أمر الشرطة المائلة /summary: رسالة مستخدم مرئية + تعليمات مخفية. غير مدمر - لا يضغط سجل الجلسة.",
  "settings.magicPrompts.page.group.sessionWorkspaceReview.title": "مراجعة مساحة العمل",
  "settings.magicPrompts.page.group.sessionExplore.title": "جولة قاعدة التعليمات البرمجية",
  "settings.magicPrompts.page.group.sessionExplore.description": "المطالبات المستخدمة بواسطة أمر الشرطة المائلة /explore: رسالة مستخدم مرئية + تعليمات مخفية. يقوم بالتحقق من المستودع ويقدم توجيهًا منظمًا - الصورة الكبيرة، والوحدات الرئيسية، وكيفية اتصالها، ومن أين تبدأ - بدلاً من تفريغ ملف تلو الآخر.",
  "settings.magicPrompts.page.group.sessionWorkspaceReview.description": "المطالبات المستخدمة بواسطة أمر الشرطة المائلة /workspace-review: رسالة مستخدم مرئية + تعليمات مخفية. يراجع اختلاف مساحة العمل لمعرفة ما إذا كانت تحقق هدفها وما إذا كانت صحيحة وكافية، مع تصنيف النتائج حسب خطورتها.",
  "settings.magicPrompts.page.group.sessionFeaturePlan.title": "تخطيط الميزات",
  "settings.magicPrompts.page.group.sessionFeaturePlan.description": "المطالبات المستخدمة بواسطة أمر الشرطة المائلة /plan-feature: رسالة مستخدم مرئية + تعليمات مخفية. يدير حوارًا موجهًا يبحث في الكود ويطرح أسئلة توضيحية على دفعات صغيرة قبل إنتاج خطة التنفيذ.",
  "settings.magicPrompts.page.group.sessionCatchUp.title": "الحق",
  "settings.magicPrompts.page.group.sessionCatchUp.description": "المطالبات المستخدمة بواسطة أمر الشرطة المائلة /catch-up: رسالة مستخدم مرئية + تعليمات مخفية. يبني سياقًا مدركًا للفرع — التزامات الفرع، والعلاقات العامة الخاصة به، والعمل غير الملتزم معًا — لفهم ما كنت تفعله، ثم يقدم ملخصًا سهل الفهم وخطوة تالية تركز على المنتج.",
  "settings.magicPrompts.page.group.sessionDebug.title": "تصحيح الأخطاء",
  "settings.magicPrompts.page.group.sessionDebug.description": "المطالبات المستخدمة بواسطة أمر الشرطة المائلة /debug: رسالة مستخدم مرئية + تعليمات مخفية. إجراء تحقيق موجه في السبب الجذري — يلتقط الأعراض، ويشكل فرضيات، ويفحصها مقابل الكود، ويؤكد السبب قبل اقتراح الإصلاح.",
  "settings.magicPrompts.page.group.sessionWeigh.title": "خيارات الوزن",
  "settings.magicPrompts.page.group.sessionWeigh.description": "المطالبات المستخدمة بواسطة أمر الشرطة المائلة /weigh: رسالة مستخدم مرئية + تعليمات مخفية. يقوم بالتحقيق في الكود، ثم يضع 2-3 أساليب متميزة مع المفاضلات والتوصية - دون كتابة خطة أو كود.",
